import React from "react";
import { StatusBadge } from "../../index";
import "./CardWithBackground.scss";

export interface CardWithBackgroundProps {
  id?: string;
  cardType?: "elevated" | "filled" | "outline";
  types?: "Card01" | "Card02";
  imageUrl?: string;
  title?: string;
  subText?: string;
  showStatusBadge?: boolean;
  badgeText?: string;
  onCardClick?: () => void;
  disabled?: boolean;
}

const CardWithBackground: React.FC<CardWithBackgroundProps> = ({
  id,
  cardType = "elevated",
  types = "Card01",
  imageUrl,
  title,
  subText,
  showStatusBadge = true,
  badgeText,
  onCardClick,
  disabled = false,
}) => {
  return (
    <div
      id={id}
      className={`mpa-cardBackgroundWrapper ${disabled ? "disabled" : ""} ${cardType}`}      
      style={{ backgroundImage: `url(${imageUrl})` }}
      tabIndex={disabled ? -1 : 0}
      role="button"
      onClick={!disabled ? onCardClick : undefined}
      onKeyDown={(e) => {
        if (!disabled && (e.key === "Enter" || e.key === " ")) {
          e.preventDefault();
          onCardClick?.();
        }
      }}
      aria-disabled={disabled}
    >
      <div className="mpa-cardBackgroundBadge">
        {showStatusBadge && (
          <StatusBadge
            shape="semi-rounded"
            id="statusBadgeId"
            size="medium"
            label={badgeText}
            colour="primary"
          />
        )}
      </div>
      <div
        className={`mpa-cardBackgroundOverlayContent ${
          types === "Card02" ? "top-position" : ""
        }`}
      >
        <div className="mpa-cardBackgroundOverlayTitle">{title}</div>
        <div className="mpa-cardBackgroundOverlaySubtitle">{subText}</div>
      </div>
    </div>
  );
};

export default CardWithBackground;
